import{_ as s,o as i,c as l,a3 as a,j as o,a as t,t as n}from"./chunks/framework.BTQ4eCVb.js";const b=JSON.parse('{"title":"Email — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Email — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/email"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Email — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/email"}]]},"headers":[],"relativePath":"developer-guide/email.md","filePath":"developer-guide/email.md","lastUpdated":1787698998000}'),c={name:"developer-guide/email.md"};function r(d,e,m,p,u,h){return i(),l("div",null,[e[9]||(e[9]=a('<h1 id="email-—-developer-guide" tabindex="-1">Email — Developer Guide <a class="header-anchor" href="#email-—-developer-guide" aria-label="Permalink to &quot;Email — Developer Guide&quot;">​</a></h1><p>Personal <strong>IMAP/SMTP</strong> mailbox module (<code>email</code>, catalog <strong>v1.3.0</strong>). Tenants install it from Marketplace (<code>is_default_included=false</code>, <code>is_billable=false</code>, prices <code>$0</code>). Authorization uses Spatie <code>email.*</code> permissions. Mailboxes, folders, messages, labels, and signatures are scoped to the account owner (<code>user_id</code> via <code>EmailAccount</code>). Templates support <code>is_shared</code> for workspace-wide apply.</p><p>v1.x uses <strong>app passwords / IMAP+SMTP credentials</strong> only. There is <strong>no OAuth</strong> for Gmail or Microsoft in this version.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2>',4)),o("ul",null,[e[4]||(e[4]=o("li",null,"Let each workspace user connect their own mailbox inside EloSync",-1)),e[5]||(e[5]=o("li",null,[t("Sync folders and messages over IMAP ("),o("code",null,"ext-imap"),t(")")],-1)),e[6]||(e[6]=o("li",null,"Send and save drafts over personal SMTP",-1)),o("li",null,[e[0]||(e[0]=t("Support shareable templates (",-1)),o("code",null,n(d.variables),1),e[1]||(e[1]=t(", ",-1)),e[2]||(e[2]=o("code",null,"is_shared",-1)),e[3]||(e[3]=t(") and private signatures; CRM soft-links API exists (no SPA UI in v1)",-1))]),e[7]||(e[7]=o("li",null,[t("Let each user connect "),o("strong",null,"multiple"),t(" IMAP/SMTP accounts, mark a default, and choose From when composing")],-1)),e[8]||(e[8]=o("li",null,[t("Support "),o("strong",null,"EloSync-only labels"),t(" (many-to-many on messages; not IMAP-synced)")],-1))]),e[10]||(e[10]=a('<h2 id="separation-from-platform-mail" tabindex="-1">Separation from platform mail <a class="header-anchor" href="#separation-from-platform-mail" aria-label="Permalink to &quot;Separation from platform mail&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Personal Email module</th><th>Platform / transactional mail</th></tr></thead><tbody><tr><td>Config</td><td>Per-user <code>EmailAccount</code> IMAP/SMTP credentials (encrypted passwords)</td><td><code>EmailConfigResolver</code> + Central/tenant Settings → Mail</td></tr><tr><td>Send path</td><td><code>SmtpClient</code> (<code>SymfonySmtpClient</code>)</td><td>Laravel Mail / <code>EmailManager</code> drivers</td></tr><tr><td>Queue</td><td><code>email-sync</code></td><td><code>emails</code> / <code>emails-high</code> (notifications)</td></tr><tr><td>Logs</td><td>Module tables (<code>email_messages</code>, …)</td><td><code>email_logs</code> / Email Logs UI</td></tr></tbody></table><p><strong>Do not</strong> call <code>EmailConfigResolver</code>, <code>EmailManager</code>, or Settings mail drivers for personal mailbox sync or send. Mixing them would route user mail through platform providers or steal notification queue capacity.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SPA /email</span></span>\n<span class="line"><span>  → Tenant API /api/tenant/v1/email/*</span></span>\n<span class="line"><span>      → Controllers (accounts, folders, labels, messages, templates, signatures)</span></span>\n<span class="line"><span>          → EmailAccountService / EmailSyncService / EmailMessageService / EmailLabelService / …</span></span>\n<span class="line"><span>              → MailboxClient (IMAP)  — list folders, fetch, flags, move, append</span></span>\n<span class="line"><span>              → SmtpClient (SMTP)     — test + send</span></span>\n<span class="line"><span>          → Jobs on queue email-sync</span></span>\n<span class="line"><span>              → SyncEmailAccountJob</span></span>\n<span class="line"><span>              → SendEmailMessageJob</span></span>\n<span class="line"><span>  → Schedule: email:sync every minute (due by sync_interval_minutes; withoutOverlapping)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Concern</th><th>Implementation</th></tr></thead><tbody><tr><td>Licensing</td><td>Catalog slug <code>email</code> + <code>module:email</code> middleware</td></tr><tr><td>Authorization</td><td><code>email.{view,create,update,delete,accounts.manage,templates.manage,signatures.manage}</code> + personal policies</td></tr><tr><td>IMAP</td><td><code>NativeImapMailboxClient</code> when <code>extension_loaded(&#39;imap&#39;)</code>; otherwise clear <code>RuntimeException</code></td></tr><tr><td>SMTP</td><td><code>SymfonySmtpClient</code> with dynamic mailer config from the account row</td></tr><tr><td>Tests</td><td><code>FakeMailboxClient</code> / <code>FakeSmtpClient</code> bound in testing</td></tr><tr><td>Audit</td><td>Light <code>PlatformAuditService</code> on connect / disconnect</td></tr></tbody></table><h3 id="backend-layout" tabindex="-1">Backend layout <a class="header-anchor" href="#backend-layout" aria-label="Permalink to &quot;Backend layout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Models</td><td><code>EmailAccount</code>, <code>EmailFolder</code>, <code>EmailLabel</code>, <code>EmailMessage</code>, <code>EmailAttachment</code>, <code>EmailSignature</code>, <code>EmailTemplate</code>, <code>EmailMessageLink</code></td></tr><tr><td>Enums</td><td><code>EmailFolderTypeEnum</code>, <code>EmailMessageDirectionEnum</code>, <code>EmailSyncStatusEnum</code></td></tr><tr><td>Contracts</td><td><code>app/Services/Tenant/Email/Contracts/MailboxClient.php</code>, <code>SmtpClient.php</code></td></tr><tr><td>DTOs</td><td><code>app/Services/Tenant/Email/Dto/RemoteFolder.php</code>, <code>RemoteMessage.php</code>, <code>RemoteAttachment.php</code></td></tr><tr><td>Clients</td><td><code>NativeImapMailboxClient</code>, <code>SymfonySmtpClient</code>, fakes for tests</td></tr><tr><td>Services</td><td><code>EmailAccountService</code>, <code>EmailSyncService</code>, <code>EmailMessageService</code>, <code>EmailLabelService</code>, <code>EmailTemplateService</code>, <code>EmailSignatureService</code></td></tr><tr><td>Jobs</td><td><code>SyncEmailAccountJob</code>, <code>SendEmailMessageJob</code> (<code>ShouldQueue</code>, <code>onQueue(&#39;email-sync&#39;)</code>)</td></tr><tr><td>Command</td><td><code>email:sync</code> — dispatches sync jobs for accounts that need sync</td></tr><tr><td>Controllers</td><td><code>app/Http/Controllers/Tenant/Api/V1/Email/*</code></td></tr><tr><td>Policy</td><td>Personal ownership (<code>user_id</code>) + <code>email.*</code> abilities</td></tr><tr><td>Tests</td><td><code>tests/Feature/Tenant/Email/*</code></td></tr></tbody></table><p>Bindings (e.g. <code>AppServiceProvider</code>): testing → fakes; otherwise native IMAP + Symfony SMTP.</p><h3 id="frontend-layout" tabindex="-1">Frontend layout <a class="header-anchor" href="#frontend-layout" aria-label="Permalink to &quot;Frontend layout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Inbox UI</td><td><code>src/pages/email/email-page.tsx</code> (folders + resizable list + reading pane; layout right/full; multi-select bulk toolbar)</td></tr><tr><td>Connect dialog</td><td><code>email-account-dialog.tsx</code> (Gmail / Outlook / Custom presets; multi-account)</td></tr><tr><td>Labels</td><td><code>email-labels-dialog.tsx</code>, <code>email-label-badges.tsx</code>; apply via reading-pane or bulk Labels menu</td></tr><tr><td>Reading pane</td><td><code>email-reading-pane.tsx</code> (actions, full-panel toggle, sandboxed HTML)</td></tr><tr><td>Compose</td><td><code>email-compose-dialog.tsx</code> (From select, TipTap <code>RichTextEditor</code>)</td></tr><tr><td>Shared editor</td><td><code>src/components/common/rich-text-editor.tsx</code></td></tr><tr><td>Templates / signatures</td><td><code>email-templates-page.tsx</code>, <code>email-signatures-page.tsx</code> (+ TipTap body fields)</td></tr><tr><td>Routes / nav</td><td><code>/email</code>, templates &amp; signatures children; <code>module: &#39;email&#39;</code></td></tr><tr><td>E2E</td><td><code>e2e/tests/email/</code>, <code>npm run test:e2e:email</code> (labels lifecycle, layout toggle, multi-select mark read when mailbox has mail)</td></tr></tbody></table><h2 id="data-model" tabindex="-1">Data model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data model&quot;">​</a></h2><h3 id="email-accounts" tabindex="-1"><code>email_accounts</code> <a class="header-anchor" href="#email-accounts" aria-label="Permalink to &quot;`email_accounts`&quot;">​</a></h3><p>Per-user connection. Unique <code>(tenant_id, user_id, email_address)</code>. Passwords encrypted casts. <code>sync_status</code>: <code>idle</code> | <code>syncing</code> | <code>error</code>. Soft deletes.</p><h3 id="email-folders" tabindex="-1"><code>email_folders</code> <a class="header-anchor" href="#email-folders" aria-label="Permalink to &quot;`email_folders`&quot;">​</a></h3><p>Synced remote folders (<code>remote_path</code>, <code>type</code> from <code>EmailFolderTypeEnum</code>, unread/total counts, <code>uidvalidity</code> / <code>uidnext</code>). Sync deletes local folder rows whose <code>remote_path</code> is missing remotely — <strong>do not</strong> store EloSync-only labels as folders.</p><h3 id="email-labels" tabindex="-1"><code>email_labels</code> <a class="header-anchor" href="#email-labels" aria-label="Permalink to &quot;`email_labels`&quot;">​</a></h3><p>EloSync-only labels per mailbox (<code>email_account_id</code>, <code>name</code> unique per account, optional <code>color</code> <code>#RRGGBB</code>, <code>sort_order</code>). Not touched by IMAP sync.</p><h3 id="email-message-label" tabindex="-1"><code>email_message_label</code> <a class="header-anchor" href="#email-message-label" aria-label="Permalink to &quot;`email_message_label`&quot;">​</a></h3><p>Pivot many-to-many (<code>email_message_id</code>, <code>email_label_id</code>). Labels may span folders; folder membership remains exclusive via <code>email_messages.email_folder_id</code>.</p><h3 id="email-messages" tabindex="-1"><code>email_messages</code> <a class="header-anchor" href="#email-messages" aria-label="Permalink to &quot;`email_messages`&quot;">​</a></h3><p>Cached message headers/bodies, direction (<code>inbound</code> / <code>outbound</code>), draft/read/starred flags, <code>UtcDateTime</code> for <code>sent_at</code> / <code>received_at</code>. Unique <code>(email_folder_id, message_uid)</code> when UID present. List/show resources include <code>labels</code> when eager-loaded.</p><h3 id="email-attachments" tabindex="-1"><code>email_attachments</code> <a class="header-anchor" href="#email-attachments" aria-label="Permalink to &quot;`email_attachments`&quot;">​</a></h3><p>Schema + client helpers for a future fetch/store/download path (<code>disk</code>, <code>path</code>, size, mime, inline/<code>content_id</code>). <strong>v1 sync does not download attachment bodies</strong>; it may set <code>email_messages.has_attachments</code> from headers only.</p><h3 id="email-templates-email-signatures" tabindex="-1"><code>email_templates</code> / <code>email_signatures</code> <a class="header-anchor" href="#email-templates-email-signatures" aria-label="Permalink to &quot;`email_templates` / `email_signatures`&quot;">​</a></h3><p>Templates: <code>subject</code>, <code>body_html</code>, optional <code>variables</code> JSON, <code>is_active</code>, <strong><code>is_shared</code></strong> (default <code>true</code> for new rows; existing rows backfilled <code>false</code>). Soft deletes. List scope:</p><ul><li>Management list: own templates <strong>or</strong> <code>is_shared</code>; workspace owner (<code>superadmin</code>) sees all (including others’ private) for administration.</li><li>Compose list (<code>for_compose=1</code>): own <strong>or</strong> shared, and <code>is_active</code> — even owner does not get others’ private in the picker.</li><li>Update/delete: creator <strong>or</strong> workspace owner, with <code>email.templates.manage</code>.</li><li>Resource includes <code>user</code> (creator), <code>can_edit</code>, <code>can_delete</code>. Identity for apply/render is always <code>uuid</code>.</li><li>Render of <strong>inactive</strong> templates is allowed only for users who can update them (creator / workspace owner); other entitled viewers receive 403 so inactive templates cannot be applied from compose.</li></ul><p>Signatures: personal CRUD only; <code>body_html</code>, <code>is_default</code> per user — never shared.</p><h3 id="email-message-links" tabindex="-1"><code>email_message_links</code> <a class="header-anchor" href="#email-message-links" aria-label="Permalink to &quot;`email_message_links`&quot;">​</a></h3><p>Polymorphic link (<code>linkable_type</code> / <code>linkable_id</code>) to CRM entities. API requires <code>email.update</code> <strong>and</strong> <code>Gate::authorize(&#39;view&#39;, $linkable)</code>. No Email SPA linking UI in v1.</p><h2 id="sync-send" tabindex="-1">Sync &amp; send <a class="header-anchor" href="#sync-send" aria-label="Permalink to &quot;Sync &amp; send&quot;">​</a></h2><ol><li><strong>Connect / test</strong> — <code>MailboxClient::testConnection</code> + <code>SmtpClient::testConnection</code> before persist.</li><li><strong>Sync</strong> — <code>EmailSyncService</code> via <code>SyncEmailAccountJob</code> on <code>email-sync</code>; also forced from <code>POST …/accounts/{uuid}/sync</code>.</li><li><strong>Schedule</strong> — <code>Schedule::command(&#39;email:sync&#39;)-&gt;everyMinute()-&gt;withoutOverlapping()-&gt;onOneServer()</code> in <code>routes/console.php</code>. Dispatches only accounts due per <code>sync_interval_minutes</code>.</li><li><strong>Send</strong> — compose/draft in DB → <code>SendEmailMessageJob</code> → <code>SmtpClient::send</code>; append to Sent when IMAP supports it. Reply compose may include <code>in_reply_to</code> / <code>thread_key</code>.</li><li><strong>Move / trash</strong> — <code>PUT</code> with <code>folder_uuid</code> moves on IMAP. <code>DELETE</code> moves to Trash when present; a second delete from Trash permanently removes. Soft-fail local hard-delete applies only when IMAP reports the UID missing (<code>MailboxMessageNotFoundException</code>). Auth/network/UID-resolve failures propagate so the EloSync copy is not deleted.</li><li><strong>Show / body refresh</strong> — <code>GET</code> message runs <code>EmailMessageService::show</code>. When <code>body_html</code> is <code>null</code>, the service re-fetches from IMAP once and persists HTML or <code>&#39;&#39;</code> (empty string = fetch attempted, no HTML — avoids re-hitting IMAP on every open). Transient fetch failures leave <code>null</code> so a later open can retry. <code>NativeImapMailboxClient</code> walks nested <code>multipart/*</code> parts and converts common MIME charsets to UTF-8.</li><li><strong>Labels</strong> — CRUD under <code>/email/accounts/{uuid}/labels</code> and <code>/email/labels/{uuid}</code>; <code>PUT /email/messages/{uuid}/labels</code> syncs <code>label_uuids</code> (account-scoped). <code>GET /email/labels/{uuid}/messages</code> lists across folders.</li><li><strong>Bulk</strong> — <code>POST /email/messages/bulk</code> with up to 25 <code>message_uuids</code> and <code>action</code> (<code>delete</code> | <code>move</code> | <code>flags</code> | <code>labels</code>). Reuses single-message services (IMAP before local DB for flags); label mode is <code>add</code> / <code>remove</code> (not replace-all). Returns <code>{ processed, failed[] }</code> with sanitized <code>failed[].message</code> (no raw IMAP text); HTTP 422 when none succeed. Permissions: <code>email.delete</code> for delete, <code>email.update</code> otherwise. Owned messages only.</li><li><strong>Disconnect</strong> — delete pivot labels, messages, folders, and labels for that account.</li></ol><h2 id="permission-model" tabindex="-1">Permission model <a class="header-anchor" href="#permission-model" aria-label="Permalink to &quot;Permission model&quot;">​</a></h2><p>Config: <code>config/tenant-permissions.php</code> → <code>email</code> actions.</p><table tabindex="0"><thead><tr><th>Permission</th><th>Purpose</th></tr></thead><tbody><tr><td><code>view</code></td><td>List/show accounts (own), folders, labels, messages</td></tr><tr><td><code>create</code> / <code>update</code> / <code>delete</code></td><td>Compose, draft, send, flags, move, delete messages; create/update/delete/apply labels (<code>update</code>)</td></tr><tr><td><code>accounts.manage</code></td><td>Connect, update credentials, test, sync, disconnect, default flag</td></tr><tr><td><code>templates.manage</code></td><td>Template CRUD + preview/render (edit/delete still require creator or workspace owner)</td></tr><tr><td><code>signatures.manage</code></td><td>Personal signature CRUD</td></tr></tbody></table><p>Default role map (<code>config/tenant-default-role-permissions.php</code>): admin and manager receive the full set; staff may be narrower depending on map. Superadmin/owner gets all via provisioning.</p><p>Routes: <code>module:email</code> then <code>can:email.*</code> / policies. Account/signature/message policies reject cross-user access even with matching permission strings. Template policies allow shared visibility and owner override for update/delete.</p><h2 id="production-registration-no-seeders" tabindex="-1">Production registration (no seeders) <a class="header-anchor" href="#production-registration-no-seeders" aria-label="Permalink to &quot;Production registration (no seeders)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Migration</th><th>Responsibility</th></tr></thead><tbody><tr><td>Schema</td><td><code>2026_08_06_180010</code>–<code>180016</code> email_* tables; <code>2026_08_07_*</code> <code>is_shared</code> + catalog <strong>1.1.0</strong>; labels tables + catalog <strong>1.2.0</strong>; bulk/layout SPA + catalog <strong>1.3.0</strong></td></tr><tr><td>Catalog</td><td><code>register_email_module</code> via <code>DefaultModuleRegistrar</code>; version bumps via <code>bumpVersion</code></td></tr><tr><td>Permissions</td><td><code>add_email_permissions</code> via <code>TenantPermissionSynchronizer</code></td></tr></tbody></table><p>Production:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimize</span></span></code></pre></div><p>Do <strong>not</strong> run <code>CatalogSeeder</code> or permission seeders in production for this module. See <a href="/deployment/email">deployment/email.md</a>.</p><h2 id="php-requirement-ext-imap" tabindex="-1">PHP requirement: <code>ext-imap</code> <a class="header-anchor" href="#php-requirement-ext-imap" aria-label="Permalink to &quot;PHP requirement: `ext-imap`&quot;">​</a></h2><p><code>NativeImapMailboxClient</code> requires the PHP IMAP extension. Without it, connect/sync fails with an explicit runtime error. Do <strong>not</strong> add <code>webklex/php-imap</code> (or similar Composer IMAP wrappers) for v1.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/api/tenant-v1-email">API reference</a></li><li><a href="/user-guide/email">User guide</a></li><li><a href="/deployment/email">Deployment</a></li><li><a href="/developer-guide/multi-provider-email">Multi-Provider Email</a> — platform transactional mail (separate)</li><li><a href="/developer-guide/communication-templates">Communication Templates</a></li><li><a href="/developer-guide/module-development">Module Development Standard</a></li></ul>',46))])}const f=s(c,[["render",r]]);export{b as __pageData,f as default};
